def sort_by_latency(records):
    """Sort records by latency_ms ascending."""
    return sorted(records, key=lambda r: r["latency_ms"])


def sort_by_shard(records):
    """Sort records by shard number ascending."""
    return sorted(records, key=lambda r: r["shard"])


def sort_by_hash(records):
    """Sort records by hash string ascending."""
    return sorted(records, key=lambda r: r["hash"])


def sort_by_event_id(records):
    """Sort records by event_id ascending."""
    return sorted(records, key=lambda r: r["event_id"])


def sort_by_latency_desc(records):
    """Sort records by latency_ms descending."""
    return sorted(records, key=lambda r: r["latency_ms"], reverse=True)


def filter_by_shard(records, shard):
    """Filter records matching a specific shard number."""
    return [r for r in records if r["shard"] == shard]


def filter_by_state(records, state):
    """Filter records matching a specific state string."""
    return [r for r in records if r["state"] == state]


def filter_by_latency_range(records, min_ms, max_ms):
    """Filter records with latency_ms within [min_ms, max_ms]."""
    return [r for r in records if min_ms <= r["latency_ms"] <= max_ms]


def filter_by_hash_prefix(records, prefix):
    """Filter records whose hash starts with the given prefix."""
    return [r for r in records if r["hash"].startswith(prefix)]


def filter_by_event_id_range(records, start, end):
    """Filter records with event_id within [start, end]."""
    return [r for r in records if start <= r["event_id"] <= end]


def filter_by_shard_set(records, shards):
    """Filter records whose shard is in the given set."""
    return [r for r in records if r["shard"] in shards]


def filter_by_state_not(records, state):
    """Filter records whose state is NOT the given value."""
    return [r for r in records if r["state"] != state]


def filter_by_latency_above(records, threshold):
    """Filter records with latency_ms strictly above threshold."""
    return [r for r in records if r["latency_ms"] > threshold]


